class RoutesCommand(click.Command):
    """The ``routes`` command. This command is used to list all routes
    registered on the application.
    """

    def __init__(self, app: Flask):
        self.app = app
        super().__init__(
            "routes",
            short_help="Show the routes for the app.",
            help="Show the routes for the app.",
        )

    def get_options(self):
        return [
            click.Option(
                ["-s", "--sort"],
                type=click.Choice(("endpoint", "methods", "rule", "match")),
                default="endpoint",
                help="Method to sort routes by. Default is to sort by endpoint.",
            ),
            click.Option(
                ["--all-methods"],
                is_flag=True,
                help="Show HEAD and OPTIONS methods.",
            ),
        ]

    def get_route_info(self, rule: Rule) -> t.Tuple[str, str, str]:
        """Get the route information for a rule.

        :param rule: The rule to get the information for.
        :return: A tuple of (endpoint, methods, rule).
        """
        methods = ",".join(sorted(rule.methods - {"HEAD", "OPTIONS"}))
        return rule.endpoint, methods, rule.rule

    def invoke(self, ctx: click.Context) -> t.Any:
        app = self.app
        rules = sorted(app.url_map.iter_rules(), key=attrgetter("endpoint"))
        if self.sort == "endpoint":
            rules = sorted(rules, key=attrgetter("endpoint"))
        elif self.sort == "methods":
            rules = sorted(rules, key=lambda r: ",".join(sorted(r.methods)))
        elif self.sort == "rule":
            rules = sorted(rules, key=attrgetter("rule"))
        elif self.sort == "match":
            rules = sorted(rules, key=lambda r: r.match_compare_key())

        if not rules:
            click.echo("No routes were registered.")
            return

        rows = []
        for rule in rules:
            endpoint, methods, rule_str = self.get_route_info(rule)
            if not self.all_methods:
                methods = ",".join(sorted(rule.methods - {"HEAD", "OPTIONS"}))
            rows.append((endpoint, methods, rule_str))

        headers = ("Endpoint", "Methods", "Rule")
        widths = [len(h) for h in headers]
        for row in rows:
            for i, cell in enumerate(row):
                widths[i] = max(widths[i], len(cell))

        click.echo(
            "  ".join(
                f"{header:<{width}}" for header, width in zip(headers, widths)
            )
        )
        click.echo("  ".join("-" * width for width in widths))
        for row in rows:
            click.echo(
                "  ".join(
                    f"{cell:<{width}}" for cell, width in zip(row, widths)
                )
            )
