class RoutesCommand(click.Command):
    """The ``routes`` command."""

    def __init__(self, *args, **kwargs):
        kwargs.setdefault("help", __doc__)
        super().__init__(*args, **kwargs)

    def parse_args(self, ctx, args):
        if not args and self.no_args_is_help:
            ctx.obj = None
            return super().parse_args(ctx, ["--help"])
        return super().parse_args(ctx, args)

    def collect_rules(self, app):
        """Collect all URL rules for the given app."""
        rules = list(app.url_map.iter_rules())

        # Don't show a rule if it's a built-in rule that is not
        # registered as a view function.
        for rule in rules:
            if rule.endpoint == "static" and rule.rule == "/static/<path:filename>":
                continue

        return rules

    def display_routes(self, app, rules, all_methods=False, sort="endpoint"):
        """Display the routes in a table."""
        from flask import current_app

        if not rules:
            click.echo("No routes were registered.")
            return

        ignored_methods = set(() if all_methods else ("HEAD", "OPTIONS"))

        rows = []
        for rule in rules:
            row = (
                rule.endpoint,
                ", ".join(sorted(rule.methods - ignored_methods)),
                rule.rule,
            )
            rows.append(row)

        if sort == "endpoint":
            rows.sort(key=lambda x: x[0])
        elif sort == "methods":
            rows.sort(key=lambda x: x[1])
        elif sort == "rule":
            rows.sort(key=lambda x: x[2])
        elif sort == "match":
            rows.sort(key=lambda x: current_app.url_map.bind("test.local").match(x[2])[0])

        # Calculate the maximum width of each column
        endpoint_width = max(len(row[0]) for row in rows)
        methods_width = max(len(row[1]) for row in rows)
        rule_width = max(len(row[2]) for row in rows)

        # Print the header
        click.echo(
            f"{'Endpoint':<{endpoint_width}}  {'Methods':<{methods_width}}  {'Rule':<{rule_width}}"
        )
        click.echo("-" * (endpoint_width + methods_width + rule_width + 4))

        # Print the rows
        for row in rows:
            click.echo(
                f"{row[0]:<{endpoint_width}}  {row[1]:<{methods_width}}  {row[2]:<{rule_width}}"
            )

    def get_app(self, ctx):
        """Get the Flask app from the context."""
        info = ctx.ensure_object(ScriptInfo)
        return info.load_app()

    def invoke(self, ctx):
        """Invoke the command."""
        app = self.get_app(ctx)
        rules = self.collect_rules(app)
        self.display_routes(app, rules, all_methods=ctx.params.get("all_methods", False), sort=ctx.params.get("sort", "endpoint"))
